public static ItemStack displayStack(ItemStack stack) {
    if(stack == null || stack == ItemStack.EMPTY) return ItemStack.EMPTY;
    if(!stack.isEmpty()) return stack;
    ItemStack display = stack.copy();
    display.setCount(1);
    return display;
}

